GenerateBaseServing._get_data_parallel_r.method:
@staticmethod
def _get_data_parallel_rank(raw_request: Request | None) -> int | None:
    """Pulls the data parallel rank from a header, if provided."""
    if raw_request is None:
        return None

    rank_str = raw_request.headers.get("X-data-parallel-rank")
    if rank_str is None:
        return None

    try:
        return int(rank_str)
    except ValueError:
        return None

GenerateBaseServing._get_session_id_from.method:
@staticmethod
def _get_session_id_from_headers(raw_request: Request | None) -> str | None:
    if raw_request is None:
        return None
    if value := raw_request.headers.get(SESSION_ID_HEADER):
        return value
    return None

GenerateBaseServing._get_session_id.method:
@staticmethod
def _get_session_id(
    request: ChatCompletionRequest | CompletionRequest | ResponsesRequest,
    raw_request: Request | None,
) -> str | None:
    if request.session_id:
        return request.session_id
    if value := GenerateBaseServing._get_session_id_from_headers(raw_request):
        return value
    if request.vllm_xargs:
        session_id = request.vllm_xargs.get("session_id")
        if isinstance(session_id, str) and session_id:
            return session_id
    return None

GenerateBaseServing._get_priority.method:
@staticmethod
def _get_priority(
    request: ChatCompletionRequest | CompletionRequest | ResponsesRequest,
    raw_request: Request | None,
) -> int:
    if raw_request is not None:
        priority = raw_request.headers.get(PRIORITY_HEADER)
        if priority is not None:
            try:
                return int(priority)
            except ValueError:
                pass
    return request.priority

BaseServing._base_request_id.method:
@staticmethod
def _base_request_id(
    raw_request: Request | None, default: str | None = None
) -> str | None:
    """Pulls the request id to use from a header, if provided."""
    if raw_request is not None and (
        (req_id := raw_request.headers.get("X-Request-Id")) is not None
    ):
        return req_id

    return random_uuid() if default is None else default

InputProcessor.assign_request_id.method:
@staticmethod
def assign_request_id(request: EngineCoreRequest):
    """Replace the externally supplied request ID with an internal request ID
    that adds 8 random characters in order to ensure uniqueness.
    """
    if request.external_req_id is not None:
        raise ValueError(
            "The external_req_id field should not be set on EngineCoreRequests"
            " passed to vLLM; use the request_id field."
        )
    request.external_req_id = request.request_id
    if envs.VLLM_DISABLE_REQUEST_ID_RANDOMIZATION:
        logger.warning_once(
            "VLLM_DISABLE_REQUEST_ID_RANDOMIZATION is set and will be "
            "removed in a future release. Duplicate externally-provided "
            "request IDs may cause failures and/or subtle correctness errors."
        )
    else:
        request.request_id = f"{request.external_req_id}-{random_uuid():.8}"
